return ['domain'=>'simple-ldap-login','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'nb_NO','project-id-version'=>'Simple LDAP Login 2.0.0','pot-creation-date'=>'2026-10-30T15:26:17+00:00','po-revision-date'=>'2026-10-30T15:26:17+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['Simple LDAP Login'=>'Simple LDAP Login','https://github.com/clifgriffin/simple-ldap-login'=>'https://github.com/clifgriffin/simple-ldap-login','Connect WordPress accounts to Active Directory or OpenLDAP.'=>'Koble WordPress-kontoer til Active Directory eller OpenLDAP.','Clif Griffin Development Inc.'=>'Clif Griffin Development Inc.','https://clifgriffin.com'=>'https://clifgriffin.com','User data'=>'Brukerdata','Single sign-on'=>'Én pålogging','Custom user fields'=>'Egendefinerte brukerfelt','Copy LDAP fields, such as phone number or department, to WordPress at login. Your theme or other plugins can use these values.'=>'Kopier LDAP-felt, som telefonnummer eller avdeling, til WordPress ved innlogging. Temaet ditt eller andre plugins kan bruke disse verdiene.','Field mappings'=>'Feltkartlegginger','One mapping per line: LDAP attribute:WordPress meta key:type. Example: %1$s. Types: %2$s or %3$s.'=>'Én mapping per linje: LDAP-attributt:WordPress meta-nøkkel:type. Eksempel: %1$s. Typer: %2$s eller %3$s.','Custom field storage'=>'Lagring av egendefinerte felt','Leave the defaults unless your integration uses different user meta keys.'=>'La standardene stå med mindre integrasjonen din bruker forskjellige bruker meta-nøkler.','LDAP value suffix'=>'LDAP verdi suffiks','Stores the LDAP value, such as phone_ldap.'=>'Lagrer LDAP-verdien, som phone_ldap.','WordPress value suffix'=>'WordPress verdi suffiks','Stores the editable WordPress value, such as phone_wp.'=>'Lagrer den redigerbare WordPress-verdien, som phone_wp.','Single sign-on (SSO)'=>'Én pålogging (SSO)','Sign users in to WordPress after your web server authenticates them.'=>'Logg inn brukere i WordPress etter at webserveren din autentiserer dem.','Enable single sign-on'=>'Aktiver enkel pålogging','Users do not need a second login for WordPress.'=>'Brukere trenger ikke en annen innlogging for WordPress.','Configure your web server to authenticate users and set REMOTE_USER. Enter an LDAP search account on Connection.'=>'Konfigurer webserveren din til å autentisere brukere og sette REMOTE_USER. Skriv inn en LDAP-søkekonto under Tilkobling.','Do not copy browser headers into REMOTE_USER. Block access that bypasses web server authentication.'=>'Ikke kopier nettleseroverskrifter inn i REMOTE_USER. Blokker tilgang som omgår webserverautentisering.','Web server authentication'=>'Webserverautentisering','REMOTE_USER is present.'=>'REMOTE_USER er til stede.','REMOTE_USER is missing. Check the web server configuration.'=>'REMOTE_USER mangler. Sjekk webserverkonfigurasjonen.','The update was stopped. Activate Simple LDAP Login Pro to restore LDAP login.'=>'Oppdateringen ble stoppet. Aktiver Simple LDAP Login Pro for å gjenopprette LDAP-pålogging.','Update blocked: This package does not include all Pro files. To install Free, deactivate the plugin first. Your installed files and settings are unchanged.'=>'Oppdatering blokkert: Denne pakken inneholder ikke alle Pro-filer. For å installere Gratis, deaktiver plugin-en først. Dine installerte filer og innstillinger er uendret.','WordPress could not reactivate the plugin.'=>'WordPress kunne ikke reaktivere pluginen.','Simple LDAP Login needs PHP 8.1 or later.'=>'Simple LDAP Login trenger PHP 8.1 eller nyere.','Plugin files are missing. Reinstall Simple LDAP Login from the release ZIP.'=>'Plugin-filer mangler. Installer Simple LDAP Login på nytt fra ZIP-filen.','You do not have permission to change these settings.'=>'Du har ikke tillatelse til å endre disse innstillingene.','The settings scope has changed. Open the settings page and try again.'=>'Innstillingsomfanget har endret seg. Åpne innstillingssiden og prøv igjen.','You do not have permission to view these settings.'=>'Du har ikke tillatelse til å se disse innstillingene.','Network settings'=>'Nettverksinnstillinger','Site settings'=>'Nettstedsinnstillinger','LDAP login settings'=>'LDAP påloggingsinnstillinger','Connect to LDAP, then test a login before enabling authentication.'=>'Koble til LDAP, og test deretter en pålogging før du aktiverer autentisering.','LDAP login and SSO are disabled by SLL_DISABLE_LDAP in wp-config.php.'=>'LDAP-pålogging og SSO er deaktivert av SLL_DISABLE_LDAP i wp-config.php.','Your saved settings use SSO or custom user fields. Install Simple LDAP Login Pro to use these features. Your settings are kept.'=>'Dine lagrede innstillinger bruker SSO eller tilpassede brukerfelt. Installer Simple LDAP Login Pro for å bruke disse funksjonene. Dine innstillinger er bevart.','The saved LDAP search password cannot be read. Enter it again on the Connection tab.'=>'Det lagrede LDAP-søkepassordet kan ikke leses. Skriv det inn igjen på Tilkobling-fanen.','PHP LDAP is missing. Ask your host to install it before enabling LDAP login.'=>'PHP LDAP mangler. Be om at verten din installerer det før du aktiverer LDAP-pålogging.','LDAP passwords are sent without encryption. Use StartTLS or LDAPS if your server supports it.'=>'LDAP-passord sendes uten kryptering. Bruk StartTLS eller LDAPS hvis serveren din støtter det.','Save settings'=>'Lagre innstillinger','Settings on other tabs are kept.'=>'Innstillinger på andre faner beholdes.','LDAP connection'=>'LDAP-tilkobling','LDAP login'=>'LDAP-pålogging','Enable LDAP authentication.'=>'Aktiver LDAP-autentisering.','Directory type'=>'Katalogtype','Active Directory'=>'Active Directory','OpenLDAP / other LDAP directory'=>'OpenLDAP / annen LDAP-katalog','LDAP servers'=>'LDAP-servere','One hostname or IP address per line. Servers are tried in order.'=>'Én vertsnavn eller IP-adresse per linje. Servere prøves i rekkefølge.','Base DN'=>'Base DN','Where to search for users. Example: DC=example,DC=org.'=>'Hvor å søke etter brukere. Eksempel: DC=example,DC=org.','Username suffix'=>'Brukernavn suffiks','Added to usernames without a domain. Example: @example.org.'=>'Legges til brukernavn uten domene. Eksempel: @example.org.','Windows domain'=>'Windows-domene','Short domain name, such as EXAMPLE. Takes priority over the username suffix.'=>'Kort domenenavn, som EXAMPLE. Har prioritet over brukernavn suffikset.','Connection security'=>'Tilkoblingssikkerhet','TLS requires a trusted server certificate.'=>'TLS krever et pålitelig serversertifikat.','StartTLS (recommended)'=>'StartTLS (anbefalt)','LDAPS'=>'LDAPS','Unencrypted LDAP'=>'Uten kryptert LDAP','Unencrypted LDAP requires permission on the Advanced tab.'=>'Uten kryptert LDAP krever tillatelse på fanen Avansert.','Port'=>'Port','389 for StartTLS; 636 for LDAPS.'=>'389 for StartTLS; 636 for LDAPS.','Search subfolders'=>'Søk i undermapper','Search all organizational units below the Base DN.'=>'Søk i alle organisatoriske enheter under Base DN.','LDAP search account'=>'LDAP søke konto','An LDAP account with read access to users and groups.'=>'En LDAP-konto med leseadgang til brukere og grupper.','Search account'=>'Søke konto','LDAP bind DN or account name.'=>'LDAP bind DN eller kontonavn.','Search account password'=>'Passord for søke konto','Leave blank to keep the saved password.'=>'La stå tom for å beholde det lagrede passordet.','Login rules'=>'Innloggingsregler','Require LDAP passwords'=>'Krev LDAP-passord','Block WordPress passwords except for recovery access.'=>'Blokker WordPress-passord unntatt for gjenopprettingsadgang.','Local recovery access'=>'Lokal gjenopprettingsadgang','Selected administrators'=>'Valgte administratorer','All super administrators (legacy)'=>'Alle superadministratorer (legacy)','All administrators (legacy)'=>'Alle administratorer (legacy)','Off'=>'Av','Choose who can use a WordPress password when LDAP passwords are required.'=>'Velg hvem som kan bruke et WordPress-passord når LDAP-passord kreves.','Automatic account creation'=>'Automatisk kontoopprettelse','Create a WordPress account on the first successful LDAP login.'=>'Opprett en WordPress-konto ved første vellykkede LDAP-pålogging.','Default role'=>'Standardrolle','For new accounts only.'=>'Kun for nye kontoer.','Required groups'=>'Krevde grupper','One group name per line. Users must belong to at least one. Leave blank to allow all LDAP users.'=>'Én gruppenavn per linje. Brukere må tilhøre minst én. La stå tom for å tillate alle LDAP-brukere.','Recovery accounts'=>'Gjenopprettingskontoer','For Selected administrators only. Use separate local accounts with WordPress passwords. Hold Ctrl or Command to select multiple accounts.'=>'Kun for valgte administratorer. Bruk separate lokale kontoer med WordPress-passord. Hold Ctrl eller Command for å velge flere kontoer.','Connection options'=>'Tilkoblingsalternativer','Change these only if the default values do not work with your directory.'=>'Endre disse bare hvis standardverdiene ikke fungerer med katalogen din.','LDAP timeout (seconds)'=>'LDAP timeout (sekunder)','Maximum wait for an LDAP operation. Default: 5 seconds.'=>'Maksimal ventetid for en LDAP-operasjon. Standard: 5 sekunder.','Login attribute'=>'Innloggingsattributt','Attribute used to find users. Default: uid.'=>'Attributt brukt for å finne brukere. Standard: uid.','Allow unencrypted LDAP'=>'Tillat uten kryptert LDAP','Allow passwords to be sent without encryption.'=>'Tillat at passord sendes uten kryptering.','Group search'=>'Gruppe søk','Group base DN'=>'Gruppe base DN','Leave blank to use the user Base DN.'=>'La stå tom for å bruke bruker Base DN.','Group name attribute'=>'Gruppe navn attributt','Default: cn.'=>'Standard: cn.','Group member attribute'=>'Gruppe medlem attributt','Default: memberUid. Use member or uniqueMember if groups store user DNs.'=>'Standard: memberUid. Bruk member eller uniqueMember hvis grupper lagrer bruker DNs.','Profile attributes'=>'Profil attributter','LDAP attributes copied to new WordPress accounts.'=>'LDAP attributter kopiert til nye WordPress-kontoer.','First name attribute'=>'Fornavn attributt','Last name attribute'=>'Etternavn attributt','Email attribute'=>'E-post attributt','Website attribute'=>'Nettsted attributt','Data retention'=>'Dataoppbevaring','Delete settings when removing the plugin'=>'Slett innstillinger når plugin-en fjernes','Delete saved settings and LDAP credentials when WordPress deletes the plugin. Keep user accounts.'=>'Slett lagrede innstillinger og LDAP-legitimasjon når WordPress sletter plugin-en. Behold brukerkontoer.','Test LDAP login'=>'Test LDAP-pålogging','Save your settings, then run both tests. Keep this administrator session open.'=>'Lagre innstillingene dine, og kjør deretter begge testene. Hold denne administratorøkten åpen.','Tests check the connection, password, and required groups. They do not create accounts or sign users in.'=>'Testene sjekker tilkoblingen, passordet og nødvendige grupper. De oppretter ikke kontoer eller logger inn brukere.','After both tests pass, enable LDAP and try logging in from another browser.'=>'Når begge testene er bestått, aktiver LDAP og prøv å logge inn fra en annen nettleser.','Recovery'=>'Gjenoppretting','If you are locked out, rename the simple-ldap-login folder using your hosting file manager. Log in with a WordPress administrator password, then restore the folder and correct the settings.'=>'Hvis du er låst ute, gi nytt navn til mappen simple-ldap-login ved hjelp av filbehandleren til hosting. Logg inn med et WordPress-administratorpassord, gjenopprett deretter mappen og korriger innstillingene.','For certificate errors, ask your host to configure the trusted LDAP certificate authority.'=>'For sertifikatfeil, be verten din om å konfigurere den betrodde LDAP-sertifikatmyndigheten.','LDAP tests'=>'LDAP-tester','Tests use saved settings.'=>'Tester bruker lagrede innstillinger.','1. Test connection'=>'1. Test tilkobling','Connect to LDAP and test the search account, if set.'=>'Koble til LDAP og test søke-kontoen, hvis angitt.','Test connection'=>'Test tilkobling','2. Test login'=>'2. Test pålogging','Check an LDAP username, password, and group membership.'=>'Sjekk et LDAP-brukernavn, passord og gruppemedlemskap.','LDAP username'=>'LDAP-brukernavn','LDAP password'=>'LDAP-passord','Settings saved.'=>'Innstillinger lagret.','Connection test passed.'=>'Tilkoblingstest bestått.','Cannot connect to LDAP. Check the server, port, TLS certificate, and search account.'=>'Kan ikke koble til LDAP. Sjekk serveren, porten, TLS-sertifikatet og søke-kontoen.','LDAP login test passed. No account was created.'=>'LDAP-påloggingstest bestått. Ingen konto ble opprettet.','LDAP login test failed. Check the username, password, and required groups.'=>'LDAP-påloggingstest feilet. Sjekk brukernavnet, passordet og nødvendige grupper.','Could not save settings. Check the values and try again.'=>'Kunne ikke lagre innstillinger. Sjekk verdiene og prøv igjen.','Connection'=>'Tilkobling','Access'=>'Tilgang','Advanced'=>'Avansert','Troubleshooting'=>'Feilsøking','Your LDAP login is valid, but you need a WordPress account. Contact your site administrator.'=>'Din LDAP-pålogging er gyldig, men du trenger en WordPress-konto. Kontakt nettstedadministratoren din.','Your LDAP username is not a valid WordPress username. Contact your site administrator.'=>'Ditt LDAP-brukernavn er ikke et gyldig WordPress-brukernavn. Kontakt nettstedadministratoren din.','The default WordPress role is not available. Contact your site administrator.'=>'Den standard WordPress-rollen er ikke tilgjengelig. Kontakt nettstedadministratoren din.','Could not create your WordPress account. Contact your site administrator.'=>'Kunne ikke opprette din WordPress-konto. Kontakt nettstedadministratoren din.','Use your WordPress password for this recovery account.'=>'Bruk ditt WordPress-passord for denne gjenopprettingskontoen.','License'=>'Lisens','Get Pro'=>'Få Pro','Could not check your license. Pro features remain active. Try again on the License tab.'=>'Kunne ikke sjekke lisensen din. Pro-funksjoner forblir aktive. Prøv igjen på fanen for lisens.','Your Pro license has expired. Single sign-on and custom field updates are off. Renew your license, then select Check license on the License tab.'=>'Din Pro-lisens har utløpt. Enkel pålogging og oppdateringer av tilpassede felt er av. Forny lisensen din, og velg deretter Sjekk lisens på fanen for lisens.','Activate a Pro license on the License tab to use single sign-on and custom user fields.'=>'Aktiver en Pro-lisens på fanen for lisens for å bruke enkel pålogging og tilpassede brukerfelt.','Simple LDAP Login Pro'=>'Simple LDAP Login Pro','Give staff fewer login prompts and keep user details in sync with LDAP.'=>'Gi ansatte færre innloggingsforespørsel og hold brukeropplysninger synkronisert med LDAP.','Let staff open WordPress without another login prompt. Requires authentication on your web server, such as Kerberos or NTLM.'=>'La ansatte åpne WordPress uten en annen innloggingsforespørsel. Krever autentisering på webserveren din, som Kerberos eller NTLM.','Copy phone numbers, departments, and other LDAP fields to WordPress at login. Use these values in your theme or other plugins.'=>'Kopier telefonnumre, avdelinger og andre LDAP-felt til WordPress ved innlogging. Bruk disse verdiene i temaet ditt eller andre plugins.','View plans'=>'Se planer','Open checkout in a new tab'=>'Åpne utsjekking i en ny fane','Plans and checkout use PaidCommunities. It receives your IP address and browser details.'=>'Planer og utsjekking bruker PaidCommunities. Den mottar IP-adressen din og nettleserdetaljer.','After purchase, install the Pro ZIP from your receipt. Your LDAP settings will stay in place.'=>'Etter kjøp, installer Pro ZIP fra kvitteringen din. Dine LDAP-innstillinger vil forbli på plass.','License status updated.'=>'Lisensstatus oppdatert.','Could not verify the license. Check your key and connection, then try again.'=>'Kunne ikke verifisere lisensen. Sjekk nøkkelen din og tilkoblingen, og prøv igjen.','Pro license'=>'Pro-lisens','Enter the license key from your purchase receipt.'=>'Skriv inn lisensnøkkelen fra kvitteringen din.','Not activated'=>'Ikke aktivert','Expired'=>'Utløpt','Inactive'=>'Inaktiv','License status'=>'Lisensstatus','Active'=>'Aktiv','Data shared with PaidCommunities'=>'Data delt med PaidCommunities','Activation sends your license key, site domain, plugin version, and server IP address to PaidCommunities. License checks send the same site details.'=>'Aktivering sender lisensnøkkelen din, domenet til nettstedet, pluginversjonen og serverens IP-adresse til PaidCommunities. Lisenssjekker sender de samme nettsteddetaljene.','License key'=>'Lisensnøkkel','Activate license'=>'Aktiver lisens','Deactivate license'=>'Deaktiver lisens','Check license'=>'Sjekk lisens','Select a license action.'=>'Velg en lisenshandling.','Activating license…'=>'Aktiverer lisens…','Deactivating license…'=>'Deaktiverer lisens…','License error'=>'Lisensfeil','License updated'=>'Lisens oppdatert','Pro plans'=>'Pro planer','Loading plans…'=>'Laster planer…','Could not load plans. Open checkout in a new tab.'=>'Kunne ikke laste planer. Åpne utsjekking i en ny fane.','LDAP login failed. Check your username and password or contact your site administrator.'=>'LDAP-pålogging feilet. Sjekk brukernavnet og passordet ditt eller kontakt nettstedadministratoren din.','Your account is not allowed to log in to this site.'=>'Din konto har ikke lov til å logge inn på dette nettstedet.','LDAP login is unavailable. Contact your site administrator.'=>'LDAP-pålogging er utilgjengelig. Kontakt nettstedets administrator.','PHP OpenSSL is required to save the LDAP search password.'=>'PHP OpenSSL er nødvendig for å lagre LDAP-søkepassordet.','Could not read or save the LDAP search password. Enter it again. If this continues, ask your host to check OpenSSL and the encryption key.'=>'Kunne ikke lese eller lagre LDAP-søkepassordet. Skriv det inn igjen. Hvis dette fortsetter, be verten din om å sjekke OpenSSL og krypteringsnøkkelen.','Select a recovery account on the Access tab, or turn local recovery access Off.'=>'Velg en gjenopprettingskonto på Tilgang-fanen, eller slå av lokal gjenopprettingsadgang.','Enable Allow unencrypted LDAP on the Advanced tab, or choose StartTLS or LDAPS.'=>'Aktiver Tillat ukryptert LDAP på Avansert-fanen, eller velg StartTLS eller LDAPS.','A custom field mapping uses a protected or invalid WordPress user meta key.'=>'En tilpasset feltmapping bruker en beskyttet eller ugyldig WordPress bruker meta-nøkkel.','Enter a Base DN and at least one LDAP server before enabling LDAP login.'=>'Skriv inn en Base DN og minst én LDAP-server før du aktiverer LDAP-pålogging.','WordPress could not save the settings. Try again.'=>'WordPress kunne ikke lagre innstillingene. Prøv igjen.','LDAP protocol version'=>'LDAP-protokollversjon','LDAP timeout'=>'LDAP-tid','Check the submitted settings. No changes were saved.'=>'Sjekk de innsendte innstillingene. Ingen endringer ble lagret.','Check %s. No changes were saved.'=>'Sjekk %s. Ingen endringer ble lagret.']];